use image::RgbImage;
use rayon::prelude::*;
#[derive(Clone,Debug)] pub struct Tuning{pub exposure:f32,pub contrast:f32,pub saturation:f32,pub sharpness:f32,pub denoise:f32,pub warmth:f32,pub highlight_recovery:f32,pub shadow_lift:f32}
impl Default for Tuning{fn default()->Self{Self{exposure:0.0,contrast:1.08,saturation:1.06,sharpness:0.45,denoise:0.15,warmth:0.0,highlight_recovery:0.25,shadow_lift:0.08}}}
pub fn auto_tune(src:&RgbImage)->Tuning{let mut sum=0.0;let(mut rs,mut bs,mut count)=(0.0,0.0,0u64);for p in src.as_raw().chunks_exact(3){let(r,g,b)=(p[0]as f64/255.0,p[1]as f64/255.0,p[2]as f64/255.0);sum+=0.2126*r+0.7152*g+0.0722*b;rs+=r;bs+=b;count+=1;}if count==0{return Tuning::default()}let mean=(sum/count as f64)as f32;let rm=(rs/count as f64)as f32;let bm=(bs/count as f64)as f32;Tuning{exposure:((0.46-mean)*2.0).clamp(-0.7,0.7),contrast:(1.10+(0.46-mean).abs()*0.35).clamp(0.95,1.25),saturation:1.04,sharpness:0.30,denoise:0.12,warmth:((rm-bm)*-0.8).clamp(-0.25,0.25),highlight_recovery:0.28,shadow_lift:((0.40-mean)*0.30).clamp(0.02,0.16)}}
pub fn enhance(src:&RgbImage,t:&Tuning)->RgbImage{let width=src.width()as usize;let height=src.height()as usize;let mut out=src.clone();let input=src.as_raw();out.as_mut().par_chunks_mut(3).enumerate().for_each(|(i,p)|{let j=i*3;let(mut r,mut g,mut b)=(input[j]as f32/255.0*2.0_f32.powf(t.exposure),input[j+1]as f32/255.0*2.0_f32.powf(t.exposure),input[j+2]as f32/255.0*2.0_f32.powf(t.exposure));let lum=0.2126*r+0.7152*g+0.0722*b;let shadow=(1.0-lum).powi(2)*t.shadow_lift;let highlight=lum.powi(2)*t.highlight_recovery;r+=shadow-highlight*r*0.45;g+=shadow-highlight*g*0.45;b+=shadow-highlight*b*0.45;r=(r-0.5)*t.contrast+0.5+t.warmth*0.06;g=(g-0.5)*t.contrast+0.5;b=(b-0.5)*t.contrast+0.5-t.warmth*0.06;let l=0.2126*r+0.7152*g+0.0722*b;r=l+(r-l)*t.saturation;g=l+(g-l)*t.saturation;b=l+(b-l)*t.saturation;p[0]=(r.clamp(0.0,1.0)*255.0)as u8;p[1]=(g.clamp(0.0,1.0)*255.0)as u8;p[2]=(b.clamp(0.0,1.0)*255.0)as u8;});if width>=3&&height>=3&&(t.sharpness>0.0||t.denoise>0.0){let original=out.clone();let buf=original.as_raw();out.as_mut().par_chunks_mut(3).enumerate().for_each(|(i,p)|{let x=i%width;let y=i/width;if x==0||y==0||x+1>=width||y+1>=height{return}let idx=(y*width+x)*3;let n=idx-width*3;let s=idx+width*3;let w=idx-3;let e=idx+3;for k in 0..3{let center=buf[idx+k]as f32;let avg=(buf[n+k]as f32+buf[s+k]as f32+buf[w+k]as f32+buf[e+k]as f32)*0.25;p[k]=((center*(1.0-t.denoise)+avg*t.denoise)+(center-avg)*t.sharpness).clamp(0.0,255.0)as u8;}});}out}
